// The scripted parts of the demo story, generated by tools/dataset: the buyer's volume sheet, the standard
// questionnaire, the 5 vendor replies that arrive on fast-forward, the 2 clarification replies, and the
// saved run (a perfect reading of each reply) used as a presenter-only fallback.
import demo from "@/seed/demo.json";
import type { FileKind } from "@/lib/extract/prepare";

export type ScriptedReply = {
  vendor_code: string;
  day: number;
  subject: string;
  body: string;
  attachments: { filename: string; kind: FileKind; mime: string }[];
};

export const VOLUME_SHEET = demo.lines;
export const STANDARD_QUESTIONS = demo.questions;
export const FX_RATE = demo.fx_rate;
export const REPLIES = demo.replies as ScriptedReply[];
export const CLARIFICATION_REPLIES = demo.clarification_replies as { vendor_code: string; subject: string; body: string }[];

export function savedRun(vendorCode: string, kind: "reply" | "clarification"): unknown | null {
  const list = kind === "reply" ? demo.ideal_extraction.replies : demo.ideal_extraction.clarifications;
  return list.find((r) => r.vendor_code === vendorCode) ?? null;
}

/** Day the clarification reply arrives, relative to when it was asked. */
export const CLARIFICATION_DELAY_DAYS = 2;
